// Free Game Check polls one fixed public feed through an approved Streamer.bot action.
// It announces only newly observed PC/console giveaways and retains bounded identifiers.
const MODULE_ID = 'thsv.free-game-check';
const REFRESH_ACTION_ID = '1f8e660b-3ee9-4a9a-9390-68d7e5257c11';
const RESULTS_EVENT = 'addon.thsv.free-game-check.results';
let taskId; let stopped = true; let operation = Promise.resolve();
const manifest = { contractVersion:'2.0.0-preview.1',moduleId:MODULE_ID,name:'Free Game Check',version:'2.6.0',minimumCoreVersion:'2.0.0-preview.1',maximumTestedCoreVersion:'2.0.0-preview.1', minimumBridgeVersion: '2.6.0', maximumTestedBridgeVersion: '2.6.0',dependencies:[],requiredCapabilities:[],configurationSchema:'schemas/config.json',eventSubscriptions:[RESULTS_EVENT],commandsProvided:[],actionsProvided:[{id:'free-game-check.refresh',name:'THSV Addon - Free Game Check - Refresh'}],browserSourcesProvided:[],dataStorageOwned:['data/addons/thsv.free-game-check/','data/addons/.state/thsv.free-game-check/'],installationSteps:['Import the Free Game Check Streamer.bot package and leave Refresh triggerless.','Approve Refresh in the wizard, choose destination platforms, then enable the add-on.'],uninstallationSteps:['Uninstalling preserves only bounded giveaway IDs and refresh status.'],migrations:[],healthChecks:[{id:'thsv.free-game-check.runtime',description:'Confirms bounded public giveaway discovery is available.'}] };
function text(value,max=500){return[...(typeof value==='string'?value.replace(/[\u0000-\u001f\u007f]/gu,' ').replace(/\s+/gu,' ').trim():'')].slice(0,max).join('');}
function settingsFor(context){const raw=context.settings||{};const platforms=Array.isArray(raw.deliveryPlatforms)?raw.deliveryPlatforms.filter((item)=>['twitch','youtube','kick','tiktok'].includes(item)).slice(0,4):[];return{enabled:raw.enabled===true,refreshMinutes:Number.isInteger(raw.refreshMinutes)?Math.min(1440,Math.max(60,raw.refreshMinutes)):180,maximumPostsPerRefresh:Number.isInteger(raw.maximumPostsPerRefresh)?Math.min(5,Math.max(1,raw.maximumPostsPerRefresh)):2,announceInitial:raw.announceInitial===true,deliveryPlatforms:platforms};}
function validGame(raw){const id=text(raw?.id,80);const title=text(raw?.title,160);const url=text(raw?.url,500);let parsed;try{parsed=new URL(url);}catch{return undefined;}if(!id||!title||parsed.protocol!=='https:')return undefined;return{id,title,url:parsed.href,platforms:text(raw?.platforms,120),endDate:text(raw?.endDate,80)};}
function stateFor(raw){const value=raw&&typeof raw==='object'?raw:{};return{initialized:value.initialized===true,seenIds:Array.isArray(value.seenIds)?value.seenIds.map((item)=>text(item,80)).filter(Boolean).slice(-1000):[],lastRefreshAt:text(value.lastRefreshAt,40),lastError:text(value.lastError,180)};}
async function arm(context,delay){if(taskId)context.schedule.cancel(taskId);taskId=context.schedule.after(delay,()=>{taskId=undefined;return serialize(()=>refresh(context));});}
async function refresh(context){const settings=settingsFor(context);if(stopped||!settings.enabled)return;try{await context.streamerbot.runApprovedAction(REFRESH_ACTION_ID,{});}catch{const state=stateFor(await context.state.read());await context.state.write({...state,lastError:'The approved giveaway refresh could not be dispatched.'});}await arm(context,settings.refreshMinutes*60_000);}
async function processResults(event,context){const settings=settingsFor(context);if(!settings.enabled||event.metadata?.simulated===true)return;const state=stateFor(await context.state.read());const wasInitialized=state.initialized;const games=(Array.isArray(event.payload?.games)?event.payload.games:[]).map(validGame).filter(Boolean).slice(0,100);const known=new Set(state.seenIds);const fresh=games.filter((game)=>!known.has(game.id));for(const game of games)known.add(game.id);state.initialized=true;state.seenIds=[...known].slice(-1000);state.lastRefreshAt=event.receivedAt;state.lastError='';await context.state.write(state);if(!settings.deliveryPlatforms.length||(!settings.announceInitial&&!wasInitialized))return;for(const game of fresh.slice(0,settings.maximumPostsPerRefresh))await context.chat.send({message:`Free game: ${game.title}${game.platforms?` (${game.platforms})`:''} ${game.url} - Powered by GamerPower.com`,routing:'selected',selectedPlatforms:settings.deliveryPlatforms,overflow:'truncate'});}
function serialize(work){operation=operation.then(work,work);return operation;}
export default{manifest,required:false,async start(context){stopped=false;operation=Promise.resolve();await context.state.write(stateFor(await context.state.read()));if(settingsFor(context).enabled)await arm(context,1500);},async stop(context){stopped=true;if(taskId)context.schedule.cancel(taskId);taskId=undefined;await operation.catch(()=>undefined);operation=Promise.resolve();},async onEvent(event,context){if(event.eventType===RESULTS_EVENT)await serialize(()=>processResults(event,context));}};
export{RESULTS_EVENT,stateFor,validGame};
